# Read current semver.py - get specific sections
with open("semver.py") as f:
    content = f.read()
    lines = content.split('\n')

# Find _compare method
for i, line in enumerate(lines):
    if '_compare' in line.lower() or 'def __eq__' in line or 'def __lt__' in line or 'def __gt__' in line:
        start = max(0, i-1)
        end = min(len(lines), i+20)
        print(f"=== Lines {start+1}-{end}: ===")
        for j in range(start, end):
            print(f"{j+1}: {lines[j]}")
        print()
